-- Добавляем новые термины с нормативными актами
INSERT INTO terms (term, definition, category, normative_source, example, related_terms, source_site, note) VALUES
('Персональные данные', 'Любая информация, относящаяся к прямо или косвенно определенному или определяемому физическому лицу (субъекту персональных данных).', 'Информационная безопасность', 'ФЗ РФ от 27.07.2006 № 152-ФЗ «О персональных данных»', 'ФИО, адрес, номер телефона, email', ARRAY[12, 13], 'consultant.ru', 'Базовое определение из закона о персональных данных'),
('Обработка персональных данных', 'Любое действие (операция) или совокупность действий (операций), совершаемых с использованием средств автоматизации или без использования таких средств с персональными данными.', 'Информационная безопасность', 'ФЗ РФ от 27.07.2006 № 152-ФЗ «О персональных данных»', 'Сбор, запись, систематизация, накопление, хранение, уточнение, извлечение, использование, передача, обезличивание, блокирование, удаление, уничтожение', ARRAY[11], 'consultant.ru', 'Включает все возможные операции с ПД'),
('Информация', 'Сведения (сообщения, данные) независимо от формы их представления.', 'Информационные технологии', 'ФЗ от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации»', 'Текст, изображения, звук, видео', ARRAY[14, 15], 'consultant.ru', 'Базовое определение информации из ФЗ-149'),
('Информационная система', 'Совокупность содержащейся в базах данных информации и обеспечивающих ее обработку информационных технологий и технических средств.', 'Информационные технологии', 'ФЗ от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации»', 'CRM-система, ERP-система, портал госуслуг', ARRAY[13, 15], 'consultant.ru', 'Определение из ФЗ-149'),
('Информационные технологии', 'Процессы, методы поиска, сбора, хранения, обработки, предоставления, распространения информации и способы осуществления таких процессов и методов.', 'Информационные технологии', 'ФЗ от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации»', 'Технологии баз данных, сетевые технологии, технологии программирования', ARRAY[13, 14], 'consultant.ru', 'Определение из ФЗ-149'),
('Защита информации', 'Принятие правовых, организационных и технических мер, направленных на обеспечение защиты информации от неправомерного доступа, уничтожения, модифицирования, блокирования, копирования, предоставления, распространения.', 'Информационная безопасность', 'ГОСТ Р 50922-2006 «Защита информации. Основные термины и определения»', 'Шифрование, контроль доступа, антивирусная защита', ARRAY[13, 17], 'docs.cntd.ru', 'Комплекс мер по защите информации'),
('Конфиденциальность информации', 'Обязательное для выполнения лицом, получившим доступ к определенной информации, требование не передавать такую информацию третьим лицам без согласия ее обладателя.', 'Информационная безопасность', 'ФЗ от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации»', 'Коммерческая тайна, врачебная тайна, банковская тайна', ARRAY[16, 11], 'consultant.ru', 'Одно из ключевых свойств информации'),
('Угроза безопасности информации', 'Совокупность условий и факторов, создающих потенциальную или реально существующую опасность нарушения конфиденциальности, целостности и доступности информации.', 'Информационная безопасность', 'ГОСТ Р 50922-2006 «Защита информации. Основные термины и определения»', 'Вирусы, несанкционированный доступ, утечка данных', ARRAY[16, 19], 'docs.cntd.ru', 'Определяет возможные риски ИБ'),
('Средства защиты информации', 'Технические, криптографические, программные и другие средства, предназначенные для защиты информации, средства, в которых они реализованы, а также средства контроля эффективности защиты информации.', 'Информационная безопасность', 'ГОСТ Р 50922-2006 «Защита информации. Основные термины и определения»', 'Межсетевой экран, антивирус, СКЗИ, DLP-системы', ARRAY[16, 18], 'docs.cntd.ru', 'Технические и программные решения для ЗИ'),
('Электронный документ', 'Документированная информация, представленная в электронной форме, то есть в виде, пригодном для восприятия человеком с использованием электронных вычислительных машин.', 'Информационные технологии', 'ФЗ от 27.07.2006 № 149-ФЗ «Об информации, информационных технологиях и о защите информации»', 'PDF-файл с ЭЦП, электронный договор, скан документа', ARRAY[13, 21], 'consultant.ru', 'Юридически значимая форма документа');

